type PageViewEvent = {
  path: string
  timestamp: number
  userAgent?: string
}

const ANALYTICS_ENDPOINT = process.env.ANALYTICS_ENDPOINT

export async function logPageView(event: PageViewEvent): Promise<void> {
  if (!ANALYTICS_ENDPOINT) {
    console.warn('[analytics] ANALYTICS_ENDPOINT is not set, skipping page view log')
    return
  }

  try {
    await fetch(ANALYTICS_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(event),
      // The response body is not needed for fire-and-forget analytics.
      cache: 'no-store',
    })
  } catch (error) {
    // Errors inside `after` never reach the user, but we still want to
    // surface them so analytics loss is observable.
    console.error('[analytics] Failed to log page view:', error)
  }
}

import { after, headers } from 'next/server'

import { logPageView } from '@/lib/analytics'

export const dynamic = 'force-dynamic'

export default function Home() {
  const headerList = headers()
  const path = headerList.get('x-path') ?? '/'

  // `after` schedules the analytics call to run after the response has been
  // flushed to the client, so logging never blocks the render.
  after(async () => {
    await logPageView({
      path,
      timestamp: Date.now(),
      userAgent: headerList.get('user-agent') ?? undefined,
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by — your visit is being counted.</p>
    </main>
  )
}

